    im->pttbl_p=calloc(1,40);((unsigned char *)im->pttbl_p)[0]=42;im->anix=3;im->aniy=4;im->anix2=2;im->file_frm=23;im->flags=0x80;memcpy(im->file_name_raw,im->n_s,16);im->file_name_raw[14]=0x76;
    auto root=fs::temp_directory_path()/("studio-clone-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));fs::create_directories(root);auto file=root/"original.IMG";CHECK(art->save(file.u8string(),error));auto saved=bytes(file);auto id=art->sprite_id(si);CloneStroke stroke;brush={};
